tube_rack_1p5ml:
// Define dimensions
$fn = 64;
length = 106; // X dimension
width = 72; // Y dimension
height = 30; // Z dimension

hole_diameter = 11.2;
hole_depth = 25;
floor_height = 5;

// Calculate hole positions
row_spacing = 16;
col_spacing = 16;

// Center the hole grid on the block
start_x = -(width / 2);
start_y = -(width / 2);

// Create the main block
block = cube([length, width, height]);

// Create the hole grid
holes = [];
for (i = [0:3]) {
    for (j = [0:5]) {
        x_pos = start_x + j * col_spacing;
        y_pos = start_y + i * row_spacing;
        hole = cylinder(hole_depth + 0.01, hole_diameter, center=true);
        translated_hole = translate([x_pos, y_pos, floor_height]) (difference() [
            hole,
            cube([hole_diameter + 0.01, hole_diameter + 0.01, floor_height])
        ]);
        holes += translated_hole;
    }
}

// Combine the block and holes
result = union() [
    block,
    holes
];

// Render the final model
result;

conical_rack_50ml:
// Define dimensions
plate_width = 130; // mm
plate_height = 90; // mm
plate_thickness = 4; // mm
tube_diameter = 30.5; // mm
wall_length = plate_width; // mm
wall_thickness = plate_thickness; // mm
wall_height = 70; // mm

// Create the base plate
base_plate = cube([plate_width, plate_height, plate_thickness]);

// Calculate hole positions
hole_radius = tube_diameter / 2;
hole_spacing_x = 40; // centre-to-centre distance
hole_spacing_y = 40; // centre-to-centre distance
num_holes_per_row = 3;

// Create the holes
holes = [];
for (i = [0:num_holes_per_row-1]) {
    for (j = [0:1]) {
        x_offset = i * hole_spacing_x - (num_holes_per_row - 1) * hole_spacing_x / 2;
        y_offset = j * hole_spacing_y - hole_spacing_y;
        holes += translate([x_offset, y_offset, 0]) cylinder(h = plate_thickness + 1, r = hole_radius, $fn = 64);
    }
}

// Create the side walls
left_wall = translate([-wall_thickness/2, 0, 0]) cube([wall_thickness, plate_height, wall_height]);
right_wall = translate([plate_width - wall_thickness/2, 0, 0]) cube([wall_thickness, plate_height, wall_height]);

// Combine all parts
rack = base_plate - holes + left_wall + right_wall;

// Output the model
render(rack);

slide_drying_rack:
// Dimensions
base_length = 90; // X dimension of the base block
base_width = 45; // Y dimension of the base block
base_height = 20; // Z dimension of the base block

slot_length = 77; // Length of each slot
slot_width = 1.6; // Width of each slot
slot_depth = 10; // Depth of each slot

slot_spacing = 3.5; // Spacing between centers of adjacent slots

$fn = 64; // Number of facets for smooth surfaces

// Base block
base = cube([base_length, base_width, base_height]);

// Slots
slots = for(i = [0:9]) 
    translate([(i * (slot_length + slot_spacing)) - (base_length / 2) + (slot_length / 2), base_width / 2 - (slot_width / 2), 0])
        linear_extrude(height = slot_depth)
            rectangle(size = [slot_length, slot_width], center = true);

// Drying rack
drying_rack = difference() {
    base;
    slots;
};

pcr_tube_rack_sbs:
// Define dimensions
$fn = 64;

// Dimensions of the rack
block_length = 127.76; // X
block_width = 85.48;  // Y
block_height = 20;    // Z

// Dimensions of the holes
hole_diameter = 6.2;
hole_spacing = 9.0;

// Positioning of the first hole (A1)
first_hole_offset_x = 14.38;
first_hole_offset_y = 11.24;

// Chamfer details
chamfer_leg_length = 5;
chamfer_angle = 45;

// Calculate the number of holes along each axis
num_columns = 12;
num_rows = 8;

// Create the main block
block = cube([block_length, block_width, block_height]);

// Create the holes
holes = for (i = [0:num_rows-1], j = [0:num_columns-1]) {
    translate([(first_hole_offset_x + i * hole_spacing), (first_hole_offset_y + j * hole_spacing), 0])
        cylinder(h=block_height, r=hole_diameter/2, center=true);
};

// Create the chamfer
chamfer = translate([first_hole_offset_x, first_hole_offset_y, 0])
    rotate(chamfer_angle / 2)
    linear_extrude(height=chamfer_leg_length, convexity=10)
    polygon(points=[[0, 0], [chamfer_leg_length, 0], [chamfer_leg_length, chamfer_leg_length], [0, chamfer_leg_length]]);

// Combine the block, holes, and chamfer
result = difference() {
    union() {
        block;
        holes;
    }
    chamfer;
};

// Output the result
render(result);

gel_comb_10well:
// Define dimensions
$fn = 64;

plate_thickness = 1.5;
spine_length = 70;
spine_width = 12;
tooth_width = 5.0;
tooth_height = 12;
gap_between_teeth = 1.5;

// Calculate total width of the comb including gaps
total_comb_width = spine_width + 10 * tooth_width + 9 * gap_between_teeth;

// Create the comb
comb = difference() {
    // Plate
    cube([total_comb_width, spine_length, plate_thickness], center=true);

    // Spine
    translate([-total_comb_width/2 + spine_width/2, 0, 0])
        cube([spine_width, spine_length, plate_thickness]);

    // Teeth
    for (i=[0:9]) {
        translate([-total_comb_width/2 + spine_width/2 + i*(tooth_width + gap_between_teeth), -tooth_height/2, 0])
            cube([tooth_width, tooth_height, plate_thickness]);
    }
};

// Output the comb
comb;

micropestle_1p5ml:
// Define dimensions
handle_diameter = 8;
handle_height = 45;
cone_height = 17;
tip_radius = 1.5;
groove_width = 2;
groove_depth = 1;
groove_spacing = 15;

// Calculate cone radius at base
cone_base_radius = handle_diameter / 2;

// Create the cylindrical handle
handle = cylinder(r=handle_diameter/2, h=handle_height);

// Create the conical section
cone = cylinder(r1=cone_base_radius, r2=tip_radius, h=cone_height, center=true) + 
      translate([0, 0, handle_height]) * cylinder(r=tip_radius, h=0.1); // Extend slightly above

// Create the spherical tip
tip = sphere(r=tip_radius);

// Combine the parts
pestle = handle + translate([0, 0, handle_height + cone_height]) * cone + translate([0, 0, handle_height + cone_height + tip_radius]) * tip;

// Add grooves to the handle
for (z = [10:groove_spacing:25]) {
    groove = cylinder(r=handle_diameter/2 - groove_width/2, h=groove_depth, center=true);
    pestle -= translate([0, 0, z]) * groove;
}

// Render the final model
translate([-handle_diameter/2, -handle_diameter/2, 0]) * pestle;

lab_funnel_60mm:
