funnel;

seed_sowing_template:
// Define dimensions
dish_diameter = 90;
template_diameter = 85;
template_thickness = 2;
hole_diameter = 3;
hole_spacing = 9;
notch_width = 10;
notch_depth = 4;

// Calculate half dimensions for centering
half_template_diameter = template_diameter / 2;
half_notch_width = notch_width / 2;

// Create the main template disc
template_disc = cylinder(h = template_thickness, r = template_diameter / 2);

// Create the hole grid
holes = [];
for (i = [0:6]) {
    for (j = [0:6]) {
        holes += translate([i * hole_spacing, j * hole_spacing, 0]) (cylinder(h = template_thickness + 0.1, r = hole_diameter / 2));
    }
}

// Create the notch
notch = translate([0, (dish_diameter - template_diameter) / 2 - half_notch_width, 0]) (
    linear_extrude(height = template_thickness + 0.1)
    (polygon(points = [
        [-half_notch_width, -notch_depth],
        [half_notch_width, -notch_depth],
        [half_notch_width, 0],
        [-half_notch_width, 0]
    ]))
);

// Combine all elements
result = difference() {
    union() {
        template_disc;
        holes;
    }
    notch;
};

// Render the model
render();

dshaft_knob_6mm:
// Dimensions
knob_diameter = 30;
knob_height = 15;
bore_diameter = 6.2;
bore_depth = 12;
flat_to_opposite_side = 4.7;
groove_width = 2;
groove_height = 15;
pointer_groove_width = 1.5;
pointer_groove_depth = 1;

// Calculate radiuses
knob_radius = knob_diameter / 2;
bore_radius = bore_diameter / 2;
groove_radius = groove_width / 2;
pointer_groove_radius = pointer_groove_width / 2;

// Create the main cylinder
knob = cylinder(r=knob_radius, h=knob_height);

// Create the D-shaped blind bore
bore_circle = cylinder(r=bore_radius, h=bore_depth);
bore_cutout = cylinder(r=bore_radius + 0.01, h=bore_depth + 0.01);
bore_hole = cylinder(r=knob_radius - bore_radius, h=bore_depth + 0.01);
bore_flat = translate([0, 0, bore_depth]) * cylinder(r=bore_radius, h=0.01);
bore = difference() {
    union() {
        bore_circle;
        translate([0, 0, 0.01]) * bore_cutout;
    }
    translate([0, 0, 0.01]) * bore_hole;
    translate([0, 0, bore_depth - flat_to_opposite_side]) * bore_flat;
};

// Create the grip grooves
grooves = for(i=[0:17])
    rotate([0, i*20, 0]) * translate([knob_radius - groove_radius, 0, 0]) *
    cylinder(r=groove_radius, h=groove_height);

// Create the pointer groove
pointer_groove = translate([0, 0, knob_height - pointer_groove_depth]) *
    cylinder(r=pointer_groove_radius, h=pointer_groove_depth);

// Combine all parts
result = union() {
    knob;
    bore;
    grooves;
    pointer_groove;
};

// Render the model
render(result);

