hose_barb_reducer_8_5:
// Dimensions
inner_diameter_8mm_tubing = 8;
outer_diameter_8mm_barb_bottom = 7.5;
outer_diameter_8mm_barb_top = 9.5;
height_8mm_barb = 10;

inner_diameter_5mm_tubing = 5;
outer_diameter_5mm_barb_bottom = 6.5;
outer_diameter_5mm_barb_top = 5.0;
height_5mm_barb = 8;

collar_diameter = 12;
collar_height = 5;

bore_diameter = 3;
total_length = 41;

$fn = 64;

// Function to create a barb
module barb(inner_dia, outer_dia_bottom, outer_dia_top, height) {
    linear_extrude(height)
        polygon(points=[
            [0, 0],
            [inner_dia/2, 0],
            [outer_dia_top/2, height/2],
            [outer_dia_bottom/2, height],
            [inner_dia/2, height]
        ]);
}

// Main model
difference() {
    // Cylindrical section with bore
    cylinder(h=total_length, r=bore_diameter/2);

    // 8mm tubing barbs
    for (i=[0, 1]) {
        translate([0, 0, i * (height_8mm_barb + 0.01)])
            barb(
                inner_dia=inner_diameter_8mm_tubing,
                outer_dia_bottom=outer_diameter_8mm_barb_bottom,
                outer_dia_top=outer_diameter_8mm_barb_top,
                height=height_8mm_barb
            );
    }

    // Collar
    translate([0, 0, 20])
        cylinder(h=collar_height, r=collar_diameter/2);

    // 5mm tubing barbs
    for (i=[0, 1]) {
        translate([0, 0, 25 + i * (height_5mm_barb + 0.01)])
            barb(
                inner_dia=inner_diameter_5mm_tubing,
                outer_dia_bottom=outer_diameter_5mm_barb_bottom,
                outer_dia_top=outer_diameter_5mm_barb_top,
                height=height_5mm_barb
            );
    }
}

