stirrer_fan_housing:
// Dimensions
fan_diameter = 90; // Outer diameter of the fan
wall_thickness = 2.5; // Thickness of the walls
top_plate_thickness = 2; // Thickness of the top plate
notch_width = 12; // Width of the notch for the power cable
notch_depth = 8; // Depth of the notch for the power cable
notch_height = 8; // Height of the notch from the bottom of the wall

// Calculate inner dimensions
inner_diameter = fan_diameter - 2 * wall_thickness;
inner_radius = inner_diameter / 2;

// Create the top plate
top_plate = cube([fan_diameter, fan_diameter, top_plate_thickness]);

// Create the walls
walls = [];
for (i = [0:3]) {
    angle = i * 90;
    wall = rotate(angle) [
        translate([inner_radius, 0, 0]) cylinder(r=inner_radius, h=wall_thickness),
        translate([fan_diameter/2, 0, 0]) rotate_extrude() polygon(points=[[-inner_radius, 0], [-inner_radius, wall_thickness], [inner_radius, wall_thickness], [inner_radius, 0]])
    ];
    walls += wall;
}

// Create the notch for the power cable
notch_position = [fan_diameter/2, 0, 0];
notch = translate(notch_position) [
    translate([-notch_width/2, 0, 0]) cube([notch_width, wall_thickness, notch_depth]),
    translate([0, 0, 0]) rotate_extrude() polygon(points=[[-notch_width/2, 0], [-notch_width/2, wall_thickness], [notch_width/2, wall_thickness], [notch_width/2, 0]])
];

// Combine all parts
stirrer_housing = union(top_plate, walls, notch);

// Render the model
render(stirrer_housing);

nema17_motor_bracket:
// Define dimensions
base_x = 50; // x range of the base plate
base_y = 45; // y range of the base plate
base_z = 5;  // height of the base plate

motor_plate_x = 50; // x range of the motor plate
motor_plate_y = 5;  // y range of the motor plate
motor_plate_z = 50; // height of the motor plate

boss_radius = 4.5; // radius of the motor boss hole
boss_height = 28; // height of the motor boss hole from the base

screw_hole_diameter = 3.4; // diameter of the screw holes
screw_hole_spacing = 31; // spacing between screw holes

gusset_thickness = 5; // thickness of the gussets
gusset_leg_length = 20; // length of the legs of the gussets

// Create the base plate
base_plate = cube([base_x, base_y, base_z]);

// Create the motor plate
motor_plate = translate([0, 0, base_z]) cube([motor_plate_x, motor_plate_y, motor_plate_z]);

// Cut the boss hole in the motor plate
boss_hole = translate([-motor_plate_x/2, 0, boss_height]) cylinder(r=boss_radius, h=base_z+motor_plate_z);

// Cut the screw holes in the motor plate
screw_holes = for(i=[0:screw_hole_spacing:motor_plate_x])
    translate([i-screw_hole_spacing/2, 0, base_z+motor_plate_z]) 
        cylinder(r=screw_hole_diameter/2, h=motor_plate_z);

// Combine the base and motor plates
part = base_plate + motor_plate - boss_hole - screw_holes;

// Add the gussets
left_gusset = translate([-base_x/2, 0, base_z]) 
    rotate([90, 0, 0]) 
    linear_extrude(height=gusset_thickness)
    polygon(points=[[0, 0], [gusset_leg_length, 0], [gusset_leg_length, gusset_leg_length], [0, gusset_leg_length]]);

right_gusset = translate([base_x/2, 0, base_z]) 
    rotate([90, 0, 0]) 
    linear_extrude(height=gusset_thickness)
    polygon(points=[[0, 0], [-gusset_leg_length, 0], [-gusset_leg_length, gusset_leg_length], [0, gusset_leg_length]]);

part += left_gusset + right_gusset;

// Translate the part to center it on the origin
part = translate([-base_x/2, base_y/2, 0]) part;

// Set the number of facets for smoothness
$fn = 64;

// Output the final part
part;

enclosure_box_and_lid:
// Define dimensions
box_width = 70;
box_height = 50;
box_depth = 30;

lid_width = 70;
lid_height = 50;
lid_thickness = 2;

lip_width = 65.6;
lip_height = 45.6;
lip_wall_thickness = 1.5;
lip_clearance = 0.2;

// Box
box = difference() {
    cube([box_width, box_height, box_depth]);
    cube([box_width - 2*2, box_height - 2*2, box_depth - 2*2], center=true);
};

// Lid
lid = difference() {
    cube([lid_width, lid_height, lid_thickness]);
    cube([lip_width + 2*lip_clearance, lip_height + 2*lip_clearance, lip_wall_thickness + 2*lip_clearance], center=true);
};

// Ensure the lid fits inside the box
assert(lip_width < box_width - 2*2 - 2*lip_clearance);
assert(lip_height < box_height - 2*2 - 2*lip_clearance);

// Combine the parts
union() {
    translate([0, 0, 0]) box;
    translate([box_width + 10, 0, 0]) lid; // 10mm gap between parts
}

mini_gel_tank:
// Define dimensions
$fn = 64;

wall_thickness = 3;
floor_thickness = 3;
tank_width = 120;
tank_height = 40;
tank_depth = 70;
platform_length = 60;
platform_height = 10;
buffer_chamber_height = tank_height - platform_height - floor_thickness;
electrode_hole_diameter = 2;
electrode_hole_depth = 30;

// Calculate inner dimensions
inner_wall_thickness = wall_thickness - floor_thickness;
inner_tank_width = tank_width - 2 * inner_wall_thickness;
inner_tank_height = tank_height - 2 * inner_wall_thickness;
inner_tank_depth = tank_depth - 2 * inner_wall_thickness;
inner_platform_length = platform_length - 2 * inner_wall_thickness;
inner_buffer_chamber_height = buffer_chamber_height - 2 * inner_wall_thickness;

// Create the tank
tank = difference() {
    cube([tank_width, tank_depth, tank_height]);
    translate([inner_wall_thickness, inner_wall_thickness, inner_wall_thickness])
        cube([inner_tank_width, inner_tank_depth, inner_tank_height]);
};

// Create the platform
platform = translate([0, (tank_depth - platform_height) / 2, platform_height + floor_thickness])
    cube([tank_width, inner_platform_length, platform_height]);

// Create the buffer chambers
left_buffer_chamber = translate([0, 0, floor_thickness])
    cube([inner_wall_thickness, inner_tank_depth, inner_buffer_chamber_height]);
right_buffer_chamber = translate([inner_tank_width - inner_wall_thickness, 0, floor_thickness])
    cube([inner_wall_thickness, inner_tank_depth, inner_buffer_chamber_height]);

// Create the electrode holes
left_electrode_hole = translate([(tank_width - electrode_hole_diameter) / 2, 0, electrode_hole_depth])
    cylinder(d = electrode_hole_diameter, h = electrode_hole_depth);
right_electrode_hole = translate([-(tank_width - electrode_hole_diameter) / 2, 0, electrode_hole_depth])
    cylinder(d = electrode_hole_diameter, h = electrode_hole_depth);

// Combine all parts
result = union() {
    tank;
    platform;
    left_buffer_chamber;
    right_buffer_chamber;
    left_electrode_hole;
    right_electrode_hole;
};

// Render the result
result;
